"""An editorial first tree of original future milestones, not verified causal science.
Every arrow is a scoped hypothesis derived from original descriptions. No source is
represented as proving a broad dependency. No old prerequisite row is imported.
"""
from pathlib import Path
import json, collections
ROOT=Path(__file__).resolve().parents[1]
c=json.loads((ROOT/'web/data/milestones.json').read_text());M={m['id']:m for m in c['milestones']};E=[]
def edge(a,b,kind,mechanism,limit,confidence='moderate',research=None,alternative=None):
 assert a in M and b in M
 E.append(dict(id=f'TREE-{len(E)+1:03d}',fromId=a,toId=b,kind=kind,epistemicStatus='editorial-hypothesis',confidence=confidence,confidenceMeaning='Qualitative editorial assessment of conceptual fit, not a probability or scientific validation.',rationale=mechanism,uncertainty=limit,provenance={'origin':'New interpretation of the original milestone descriptions; no legacy prerequisite imported.','review':'Conceptual fit reviewed against both source descriptions; dependency not experimentally validated.','sourceMilestones':[dict(id=id,workbook=M[id]['provenance']['workbook'],sheet='Master Table',row=M[id]['provenance']['row'],description=M[id]['description']) for id in [a,b]],'reviewedAt':'2026-10-30'},resultIds=research or [],alternativeGroup=alternative))
# Learning, embodiment, manipulation and field autonomy.
edge('MLC-02','ROB-04','enabling','Continual learning could supply retention of previously learned skills in the proposed cross-embodiment learner.','Retention alone does not establish one-shot learning or transfer between robot bodies.')
edge('MLC-03','ROB-04','enabling','Learning from few examples could reduce demonstrations needed when adapting a skill to another robot.','Human-like sample efficiency does not itself solve embodiment differences.')
edge('MLC-06','ROB-07','enabling','Causal and counterfactual models could supply a reasoning component for the proposed physical common-sense engine.','This is a proposed component relationship, not a proven necessary architecture.',research=['EV-GNS'])
edge('ROB-07','ROB-01','enabling','Reasoning about object affordances could help choose manipulation strategies for unfamiliar objects.','Reasoning does not supply dexterous hardware, contact control or universal success.',research=['EV-RT2','EV-DIFF'])
edge('ROB-08','ROB-01','enabling','Compliant actuators and distributed sensing could provide physical control and feedback for dexterous handling.','Hardware performance would not establish a universal manipulation algorithm.')
edge('ROB-04','ROB-01','accelerator','Transferring learned skills could reduce retraining across hands and object-handling tasks.','Universal dexterity could use other learning architectures; transfer is not a prerequisite.')
edge('ROB-01','ROB-06','enabling','Dexterous handling could allow a robot to remove and replace damaged hardware modules.','Manipulation does not supply replacement material, diagnosis or self-reconfiguring hardware.')
edge('ROB-10','ROB-06','accelerator','Task-informed body design could help plan modular shapes and interfaces for reconfiguration.','An optimal-body theory is not required for practical modular repair.')
edge('ROB-10','ROB-03','accelerator','Co-designing body shape and control could reduce the energy needed for a specified task.','The proposed design theory does not establish biological energy efficiency.')
edge('ROB-08','ROB-03','enabling','New actuator designs could contribute to lower-energy motion at a specified load.','Compliant or low-cost actuation is not automatically energy efficient.')
edge('ROB-09','ROB-02','accelerator','Verifying planned robot behavior could support a scoped human-interaction safety argument.','Software proofs cannot establish zero physical risk under arbitrary human behavior or failures.')
edge('ROB-01','AGR-07','enabling','Handling irregular plants and produce could provide a manipulation component of autonomous field work.','A farming system still needs navigation, agronomy and robust operation under field conditions.')
edge('ROB-05','AGR-07','enabling','Decentralized coordination could organize many field robots working together.','Swarm capability does not establish crop decisions, maintenance or zero human labor.')
edge('ROB-02','AGR-07','accelerator','Safer interaction designs could help field machines operate around workers and bystanders.','The source safety aspiration is not assumed achieved, and zero-risk guarantees are not asserted.')
edge('ROB-07','AGR-07','accelerator','Reasoning about unfamiliar physical situations could help robots recover from field obstacles.','This does not establish reliable agronomic decisions or fully autonomous farming.')
