# Small, coherent branch windows. Fields/focus can expose the wider cross-field tree.
P=[('manipulation','Robotic manipulation',['MLC-02','MLC-03','MLC-06','ROB-04','ROB-07','ROB-08','ROB-01','ROB-06']),('field-robots','Autonomous field work',['ROB-07','ROB-08','ROB-01','ROB-05','ROB-09','ROB-02','AGR-07']),('software','Verified software systems',['SWE-02','SWE-01','CSC-08','SWE-07','SWE-03','SWE-08','SWE-10']),('electrolytes','Electrolyte discovery',['CHM-09','CRX-05','CRX-02','CRX-09','CRX-10','CRX-06','MAS-03']),('regulation','Regulatory biology',['GEN-02','GEN-06','BIF-01','BIF-03','BIF-02','BIF-08','BME-07','LON-05']),('longevity','Aging intervention components',['PHA-07','LON-03','LON-05','LON-07','LON-08','IMM-10','LON-09','LON-01']),('regeneration','Regeneration and replacement',['BME-01','BME-06','CLM-09','BME-03','BME-08','BME-05','BME-02','NEU-04','NRL-08','NRL-02']),('nitrogen','Nitrogen fixation and crops',['BCH-02','CHM-03','BIF-10','BOT-03','AGR-01','CHE-04']),('manufacturing','Biomanufacturing and fibers',['CHE-03','CHE-02','CHE-08','CHE-06','CHE-10','MAS-07']),('power','Self-healing power systems',['PWR-02','PWR-03','PWR-08','PWR-06','SWE-02','SWE-07','PWR-05']),('nuclear','Long-service nuclear systems',['NUC-04','NUC-05','NUC-08','NUC-06','NUC-01','MAS-02']),('enzymes','Designing artificial enzymes',['GEN-02','BIF-03','BIF-06','BCH-01','BCH-04','CHM-02','PHA-05','ONC-02']),('efficient-hardware','Energy-efficient computation',['CPE-07','CPE-02','CPE-04','CPE-03','MLC-07'])]
# Some branch windows include context nodes; render only actual modeled edges and disclose isolates.
ids={id for e in E for id in [e['fromId'],e['toId']]}
assert len(E)==len({(e['fromId'],e['toId']) for e in E})
adj=collections.defaultdict(list);indeg={id:0 for id in ids}
for e in E:adj[e['fromId']].append(e['toId']);indeg[e['toId']]+=1
q=collections.deque(id for id,n in indeg.items() if not n);seen=[]
while q:
 id=q.popleft();seen.append(id)
 for t in adj[id]:
  indeg[t]-=1
  if not indeg[t]:q.append(t)
assert len(seen)==len(ids),'Editorial tree contains a cycle'
out=dict(schemaVersion=1,version='first-tree-2026-10-30-v1',edges=E,branches=[dict(id=id,title=title,nodeIds=[n for n in ns if n in ids]) for id,title,ns in P],policy={'scope':'A first editorial tree of possible relationships between the original future milestones. No milestone achievement, date or experimentally established prerequisite is asserted.','direction':'Arrows run from a proposed input capability toward a proposed downstream use. They are not a promised chronology.','types':{'enabling':'Could provide a component or method; not established necessary or sufficient.','accelerator':'Could reduce effort, constraints or evaluation cost; not required.','alternative-route':'Another research approach toward the target; routes may combine and are not sufficient alternatives.'},'required':'No required dependency is asserted: the broad source ambitions do not justify claiming a full milestone universally necessary for another.','provenance':'Every arrow is grounded in its two original descriptions. Optional checked papers are context only, never proof of the whole relationship.'})
(ROOT/'web/data/tree.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'connectedNodes':len(ids),'edges':len(E),'types':dict(collections.Counter(e['kind'] for e in E)),'fields':len({M[id]['field'] for id in ids}),'unmapped':660-len(ids),'branches':len(P),'requiredDependencies':0,'establishedDependencies':0},indent=2))
